INSERT INTO `about_content` (`id`, `section_key`, `title`, `content`, `content_type`, `display_order`, `is_active`, `file_url`, `file_size`, `file_name`, `created_at`, `updated_at`) VALUES
	(1, 'vision', 'Vision Statement', 'मंत्रिमण्डल सचिवालय प्रधानमंत्री के अधीन कार्य करता है। सचिवालय का प्रशासनिक प्रमुख मंत्रिमंडल सचिव होता है जो सिविल सेवा बोर्ड का पदेन अध्यक्ष भी होता है। भारत सरकार (कार्य आवंटन) नियम, 1961 के तहत मंत्रिमंडल सचिवालय को आवंटित कार्य में (i) मंत्रिमंडल और मंत्रिमंडल समितियों को सचिवीय सहायता; और (ii) कार्य के नियम शामिल हैं।', 'text', 1, 1, NULL, NULL, NULL, '2026-04-30 06:34:38', '2026-06-04 12:39:36'),
	(2, 'functions', 'Functions', 'कैबिनेट सचिवालय सीधे प्रधानमंत्री के अधीन काम करता है। सचिवालय के प्रशासनिक प्रमुख कैबिनेट सचिव होते हैं, जो सिविल सेवा बोर्ड के पदेन अध्यक्ष भी होते हैं। भारत सरकार (काम का बंटवारा) नियम, 1961 के तहत कैबिनेट सचिवालय को सौंपे गए कामों में शामिल हैं: (i) कैबिनेट और कैबिनेट समितियों को सचिवालय संबंधी सहायता देना; और (ii) काम-काज के नियम।\r\n<br><br>\r\nकैबिनेट सचिवालय, भारत सरकार (काम-काज का संचालन) नियम, 1961 और भारत सरकार (काम का बंटवारा) नियम, 1961 के प्रशासन के लिए ज़िम्मेदार है, ताकि केंद्र सरकार के मंत्रालयों/विभागों में काम-काज आसानी से हो सके। सचिवालय कैबिनेट और उसकी समितियों को सचिवालय संबंधी सहायता देता है। साथ ही, यह सचिवों की स्थायी/तदर्थ (ad hoc) समितियों के ज़रिए मंत्रालयों/विभागों के बीच तालमेल बिठाकर, उनके मतभेदों को दूर करके और आम सहमति बनाकर सरकार में निर्णय लेने में मदद करता है। इस व्यवस्था के ज़रिए नई नीतिगत पहलों को भी बढ़ावा दिया जाता है। देश में बड़े संकट की स्थितियों का प्रबंधन करना और ऐसी स्थिति में विभिन्न मंत्रालयों/विभागों की गतिविधियों में तालमेल बिठाना भी कैबिनेट सचिवालय के कामों में से एक है।\r\n<br><br>\r\n\r\n<strong>सरकारी कामकाज का बंटवारा और निपटान</strong>\r\n<ul>\r\n<li>भारत सरकार (काम का बंटवारा) नियम, 1961 (AoB नियम) और भारत सरकार (काम-काज का संचालन) नियम, 1961 (ToB नियम) भारत के संविधान के अनुच्छेद 77 (3) के तहत बनाए गए हैं। AoB नियमों की पहली अनुसूची में मंत्रालयों, विभागों, कार्यालयों और सचिवालयों का विवरण दिया गया है, जबकि दूसरी अनुसूची में भारत सरकार के विभिन्न मंत्रालयों/विभागों को सौंपे गए कामों की सूची दी गई है।</li>\r\n<li>ToB नियम भारत सरकार में कामकाज के निपटान और निर्णय लेने की प्रक्रिया तय करते हैं। भारत सरकार का कामकाज आम तौर पर मंत्रालयों/विभागों के भीतर अलग-अलग स्तरों पर संबंधित मंत्री द्वारा, या उनके सामान्य या विशेष निर्देशों के तहत निपटाया जाता है, बशर्ते ToB नियमों में बताई गई ज़रूरी अंतर-विभागीय सलाह-मशविरा किया गया हो। </li>\r\n</ul> इसके अलावा, ToB नियम उन मामलों के बारे में बताते हैं जिनके लिए प्रधानमंत्री, कैबिनेट और उसकी कमेटियों, और राष्ट्रपति की मंज़ूरी ज़रूरी होती है। जिन मामलों के लिए कैबिनेट की मंज़ूरी चाहिए, वे ToB नियमों की दूसरी अनुसूची (Second Schedule) में बताए गए हैं, और जिन मामलों के लिए कैबिनेट की कमेटियों की मंज़ूरी चाहिए, वे ToB नियमों की पहली अनुसूची (First Schedule) में बताए गए हैं। जिन मामलों को प्रधानमंत्री और राष्ट्रपति के पास भेजना ज़रूरी है, वे ToB नियमों की तीसरी अनुसूची (Third Schedule) में दिए गए हैं। इस तरह, जहाँ सरकारी कामकाज का एक बड़ा हिस्सा विभागीय स्तर पर ही निपटा लिया जाता है, वहीं कुछ खास मामले या मामलों की श्रेणियाँ, जो राष्ट्रीय नज़रिए से अहम हैं, उनके लिए कैबिनेट या कैबिनेट की किसी कमेटी की मंज़ूरी की ज़रूरत होती है।\r\n<br><br>\r\n<strong>कैबिनेट कमेटियों को सहायता</strong>\r\n<br>\r\nकैबिनेट सचिवालय द्वारा कैबिनेट और कैबिनेट कमेटियों को दी जाने वाली सचिवालय संबंधी सहायता में ये शामिल हैं:\r\n<ul>\r\n<li>प्रधानमंत्री के आदेश पर कैबिनेट और उसकी कमेटियों की बैठकें बुलाना।</li>\r\n<li>एजेंडा और एजेंडा में शामिल मामलों से जुड़े कागज़ात तैयार करना और उन्हें वितरित करना।</li>\r\n<li>चर्चाओं का रिकॉर्ड तैयार करना।</li>\r\n<li>प्रधानमंत्री की मंज़ूरी मिलने के बाद चर्चाओं का रिकॉर्ड वितरित करना।</li>\r\n<li>कैबिनेट और उसकी कमेटियों द्वारा लिए गए फैसलों के कार्यान्वयन की निगरानी करना।</li>\r\n</ul>\r\nकैबिनेट सचिवालय कैबिनेट की बैठकों के कागज़ात का संरक्षक होता है।\r\n<br><br>\r\n<strong>अंतर-मंत्रालयी समन्वय को बढ़ावा देना</strong>\r\n<br>\r\nअंतर-मंत्रालयी मामलों में, इनके लिए समन्वय की ज़रूरत होती है:\r\n<br>\r\n<ul>\r\n<li>मुश्किलों को दूर करना।</li>\r\n<li>मतभेदों को दूर करना।</li>\r\n<li>देरी को दूर करना।</li>\r\n<li>प्रशासनिक कार्रवाई में समन्वय।</li>\r\n<li>नीतियों में समन्वय।</li>\r\n</ul>\r\n<br>\r\nहालाँकि हर मंत्रालय सरकारी नीतियों, योजनाओं और कार्यक्रमों को तेज़ी से लागू करने के लिए खुद कार्रवाई करने के लिए ज़िम्मेदार होता है, लेकिन जहाँ अंतर-मंत्रालयी सहयोग की बात आती है, वहाँ वे अक्सर कैबिनेट सचिवालय की मदद लेते हैं। मंत्रालयों के बीच की समस्याओं को \'सेक्रेटरीज़ की कमिटी\' (COS) की बैठकों में सुलझाया जाता है। सरकार के अलग-अलग सचिवों की ओर से आने वाले खास मामलों और प्रस्तावों पर चर्चा करने के लिए ये कमेटियां बनाई जाती हैं और इनकी बैठकें कैबिनेट सेक्रेटरी की अध्यक्षता में होती हैं। ये कमेटियां काम में आने वाली रुकावटों को दूर करने या मंत्रालयों के बीच आपसी सहयोग वाली कार्रवाई सुनिश्चित करने में सफल रही हैं।\r\n<br><br>\r\nCOS में चर्चा उस पेपर के आधार पर होती है जिसे मुख्य संबंधित विभाग तैयार करता है; अगर किसी दूसरे विभाग का नज़रिया अलग हो, तो वह एक अतिरिक्त नोट देता है। COS के फ़ैसले या सिफ़ारिशें सर्वसम्मति से होती हैं। ये कार्यवाही भी...', 'text', 2, 1, NULL, NULL, NULL, '2026-04-30 06:34:38', '2026-10-12 10:02:06'),
	(6, 'origin', 'मूल', 'भारत सरकार में विभागीय प्रणाली अपनाए जाने से पूर्व, सारा सरकारी कार्य काउन्सिल में गवर्नर-जनरल- द्वारा निपटाया जाता था। यह काउन्सिल एक संयुक्त परामर्शदात्री बोर्ड के रूप में कार्य करती थी। सरकार के कार्य में जैसे-जैसे वृद्धि हुई और उसमें जटिलता आने लगी, विभिन्न विभागों के काम को काउन्सिल के सदस्यों में बांट दिया गया। केवल अधिक महत्वपूर्ण मामलों को गवर्नर-जनरल अथवा काउन्सिल द्वारा संयुक्त रूप से निपटाया जाता था।\r\n\r\nइस प्रक्रिया को लार्ड केनिंग के कार्यकाल के दौरान काउन्सिल अधिनियम, 1861 द्वारा वैध बनाया गया जिससे विभागीय प्रणाली की शुरूआत हुई और गवर्नर-जनरल की कार्यकारिणी परिषद की स्थापना हुई। वाइसराय का निजी सचिव इस कार्यकारी परिषद के सचिवालय का प्रमुख होता था, पर वह परिषद की बैठकों में सम्मिलित नहीं होता था। लार्ड विलिंग्‍डन ने इन बैठकों में अपने निजी सचिव को अपने साथ बैठाने की प्रथा आरंभ की। बाद में यह प्रथा जारी रही और नवम्बर, 1935 में वाइसराय के निजी सचिव को कार्यकारी परिषद के सचिव का अतिरिक्त पदनाम दिया गया। लेकिन बाद में इन पदों को अलग कर दिया गया, और वायसराय तथा गवर्नर-जनरल के निजी सचिव से अलग, कार्यकारी परिषद् में एक अलग सचिव नियुक्त किया गया।\r\n\r\nसितम्बर 1946 में अंतरिम सरकार के गठन से इस कार्यालय के नाम में परिवर्तन हुआ। 5 सितम्बर, 1946 को कार्यकारी परिषद के सचिवालय को मंत्रिमंडल सचिवालय और कार्यकारी परिषद के सचिव को मंत्रिमंडल सचिव के रूप में पदनामित किया गया। तथापि, ऐसा प्रतीत होता है कि स्वतंत्रता के बाद पहले की अपेक्षा मंत्रिमंडल सचिवालय के कार्यों में एक तरह से परिवर्तन हुआ है। अब इसका कार्य मंत्रियों और मंत्रालयों को कागजात परिचालित करने के सामान्‍य कार्य तक ही सीमित नहीं है, बल्कि यह मंत्रालयों के बीच प्रभावी समन्वय के लिए एक संगठन के रूप में विकसित हुआ है।\r\n', 'text', 6, 1, NULL, NULL, NULL, '2026-04-30 06:34:38', '2026-10-12 09:50:06'),
	(7, 'development', 'Development', 'स्वतंत्रता के बाद, सन् 1949 में मंत्रिमंडल की एक आर्थिक समिति गठित की गई जिसका सचिवालय वित्त मंत्रालय में था। सन् 1950 में इसे मंत्रिमंडल सचिवालय में स्थानांतरित कर दिया गया और इसका नाम बदलकर आर्थिक स्कंध रखा गया और अंततः सन् 1955 में इस सचिवालय में इसका विलय कर दिया गया। सन् 1954 में मंत्रिमंडल सचिवालय के अंतर्गत संगठन एवं पद्धति प्रभाग की स्थापना की गई जिसे बाद में 1964 में गृह मंत्रालय को हस्तांतरित कर दिया गया। वर्तमान में, यह प्रशासनिक सुधार और लोक शिकायत विभाग के अंतर्गत है।\r\n<br><br>\r\n1 अक्टूबर, 1947 को मंत्रिमंडल की रक्षा समिति का गठन किया गया था। मंत्रिमंडल की रक्षा समिति की सेवा में मंत्रिमंडल सचिव की सहायता के लिए, अक्टूबर, 1947 में ही मंत्रिमंडल सचिवालय में एक सैन्य विंग की स्थापना की गई थी। 1970 में, सीसीपीए ने मंत्रिमंडल की रक्षा समिति और मंत्रिमंडल की आंतरिक मामलों की समिति का स्थान लिया। सीसीपीए को सचिवालयीय सहायता मंत्रिमंडल सचिवालय के सिविल विंग द्वारा प्रदान की जाती थी और मंत्रिमंडल का सैन्य विंग रक्षा मंत्री की समितियों, चीफ्स ऑफ स्टाफ कमेटियों आदि के लिए सहायता प्रदान कर रहा था। चूंकि सैन्य विंग मंत्रिमंडल सचिवालय के भीतर किसी भी कार्य से जुड़ा नहीं था और कार्यात्मक रूप से रक्षा मंत्रालय से जुड़ा हुआ था, इसलिए सैन्य विंग को 1 जुलाई, 1991 से रक्षा मंत्रालय को हस्तांतरित कर दिया गया। \r\n<br><br>\r\nसांख्यिकी विभाग का गठन अप्रैल, 1961 में मंत्रिमंडल सचिवालय के तहत किया गया था और फरवरी, 1973 में योजना मंत्रालय को हस्तांतरित कर दिया गया था। अक्टूबर, 1999 में इसे एक मंत्रालय में परिवर्तित कर दिया गया था।\r\n<br><br>\r\nविशेष आर्थिक समन्वय विभाग की स्थापना जून, 1962 में मंत्रिमंडल सचिवालय के अंतर्गत की गई थी, जिसे नवंबर, 1962 में नवगठित आर्थिक और रक्षा समन्वय मंत्रालय के अंतर्गत समन्वय विभाग के रूप में रखा गया था। इसका काम 11 सितंबर, 1963 को वित्त मंत्रालय के तहत समन्वय विभाग को हस्तांतरित कर दिया गया और 14 जून, 1967 से इस विभाग का अस्तित्व समाप्त हो गया। इसका काम वित्त मंत्रालय के तहत आर्थिक कार्य  विभाग को स्थानांतरित कर दिया गया था।\r\n<br><br>\r\nसंयुक्त खुफिया समिति को सचिवीय सहायता प्रदान करने के लिए 1965 में एक खुफिया शाखा की स्थापना की गई थी।\r\n<br><br>\r\nलोक उद्यम ब्यूरो को जनवरी, 1966 से जून, 1966 तक की छोटी अवधि के लिए मंत्रिमंडल सचिवालय के तहत लाया गया था और इसे 6 जून, 1966 को वित्त मंत्रालय के तहत समन्वय विभाग में स्थानांतरित कर दिया गया। 14 जून, 1967 को इसे वित्त मंत्रालय के तहत व्यय विभाग में स्थानांतरित कर दिया गया। 25 सितंबर, 1985 को इसे उद्योग मंत्रालय के तहत एक अलग लोक उद्यम विभाग में बदल दिया गया था, जिसे 15 अक्टूबर, 1999 को भारी उद्योग और लोक उद्यम मंत्रालय के तहत रखा गया था। 6 जुलाई, 2021 से, यह विभाग वित्त मंत्रालय के अधीन है।\r\n\r\n<br><br>\r\n<strong>जून, 1970 में मंत्रिमंडल सचिवालय के तहत निम्नलिखित तीन विभाग बनाये गए थे:</strong><br>\r\n\r\n•	इलेक्ट्रॉनिकी विभाग<br>\r\n•	वैज्ञानिक और औद्योगिक अनुसंधान विभाग, और<br>\r\n•	कार्मिक विभाग<br><br>\r\n\r\nजुलाई, 1970 में, राजस्व खुफिया महानिदेशालय-सह-प्रवर्तन निदेशालय की स्थापना मंत्रिमंडल सचिवालय के तहत मंत्रिमंडल कार्य विभाग के तहत की गई थी और बाद में इस निदेशालय को अगस्त, 1970 में कार्मिक विभाग में स्थानांतरित कर दिया गया था।<br><br>\r\n\r\nवैज्ञानिक और औद्योगिक अनुसंधान विभाग मई 1971 में स्वतंत्र विभाग बन गया और इसका नाम बदलकर विज्ञान और प्रौद्योगिकी विभाग कर दिया गया। 4 जनवरी, 1985 से, यह अपने प्रारंभिक नामकरण के साथ विज्ञान और प्रौद्योगिकी मंत्रालय के अधीन है।<br><br>\r\n\r\nइलेक्ट्रॉनिकी विभाग 1971 में स्वतंत्र विभाग बन गया और कार्मिक विभाग का नाम 07.02.1973 को कार्मिक एवं प्रशासनिक सुधार विभाग कर दिया गया। कार्मिक एवं प्रशासनिक सुधार विभाग को 1977 में मंत्रिमंडल सचिवालय से गृह मंत्रालय को स्थानांतरित कर दिया गया। वर्तमान में यह कार्मिक एवं प्रशिक्षण विभाग तथा प्रशासनिक सुधार एवं लोक शिकायत विभाग के रूप में विभाजन के साथ कार्मिक, लोक शिकायत एवं पेंशन मंत्रालय का एक हिस्सा है।\r\n<br><br>\r\nसमुद्री विकास विभाग की स्थापना जुलाई 1981 में मंत्रिमंडल सचिवालय के तहत की गई थी और फरवरी 1982 में यह स्वतंत्र विभाग बन गया। फरवरी 2006 में यह एक मंत्रालय बन गया और जुलाई 2006 से इसके कार्यों का संचालन पृथ्वी विज्ञान मंत्रालय द्वारा किया जा रहा है।\r\n\r\n<br><br>\r\n<strong>लोक शिकायत निदेशालय (डीपीजी)</strong><br><br>\r\n\r\nलोक शिकायत निदेशालय की स्थापना मार्च, 1988 में मंत्रिमंडल सचिवालय में की गई थी। एमटीएनएल/बीएसएनएल, रेलवे, डाक, बीमा कंपनियां, सार्वजनिक क्षेत्र के बैंक आदि जैसे व्यापक सार्वजनिक संपर्क वाले चुनिंदा मंत्रालयों/विभागों/संगठनों के संबंध में लोक शिकायत निदेशालय में ऑनलाइन या डाक/ड्रॉप-बॉक्स के माध्यम से शिकायतें दर्ज की जा सकती हैं (सूची https://dpg.gov.in/Authpages/OgCovered.aspx पर उपलब्ध है)।\r\n<br>\r\nशिकायतों की प्रकृति और गंभीरता के आधार पर, निदेशालय या तो टिप्पणियाँ मांगता है या उन्हें उचित कार्रवाई के लिए संबंधित विभाग (विभागों) को हस्तांतरित करता है।\r\n\r\n<br><br>\r\n<strong>राष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता (एनएसीडब्ल्यूसी)</strong>\r\n<br><br>\r\nरासायनिक हथियार समझौता (सीडब्ल्यूसी) के तहत भारत के दायित्वों को पूरा करने के लिए राष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता की स्थापना की गई थी। सीडब्ल्यूसी रासायनिक हथियारों के विकास, उत्पादन, भंडारण और उपयोग के निषेध के संबंध में एक बहुपक्षीय अंतरराष्ट्रीय संधि है। यह समझौता 29 अप्रैल, 1997 को लागू हुआ। 31 मार्च, 2025 तक, 193 पक्षकार राज्यों (देशों) ने इस संधि का अनुसमर्थन किया है या स्वीकार कर लिया है। रासायनिक हथियार निषेध संगठन (ओपीसीडब्ल्यू) हेग, नीदरलैंड में स्थित है, जो इस समझौता के लिए कार्यान्वयन निकाय है। ओपीसीडब्ल्यू को रासायनिक हथियारों के वैश्विक उन्मूलन की दिशा में इसके प्रयासों को मान्यता देने के लिए 2013 में नोबेल शांति पुरस्कार से सम्मानित किया गया था।\r\n<br>\r\nराष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता का गठन 5 मई, 1997 को मंत्रिमंडल सचिवालय द्वारा किया गया था। रासायनिक हथियार समझौता अधिनियम, 2000 (अधिनियम) 1 जुलाई, 2005 को अधिनियमित और लागू किया गया था। सीडब्ल्यूसी अधिनियम, 2000 के तहत 13 जून 2005 को प्राधिकरण की स्थापना की गई और इसे अधिसूचित किया गया था।\r\n<br>\r\nराष्ट्रीय प्राधिकरण का नेतृत्व अध्यक्ष द्वारा किया जाता है, जिसके पास भारत सरकार के सचिव के बराबर रैंक होगा और इसके विभिन्न कार्यों की देखभाल के लिए इसकी सहायता के लिए एक उपयुक्त तकनीकी सचिवालय होता है। प्राधिकरण के कार्यों की निगरानी करने और उपर्युक्त अधिनियम के प्रावधानों के अनुसार केंद्र सरकार की शक्तियों का प्रयोग करने और उनका निष्पादन करने के लिए, मंत्रिमंडल सचिव की अध्यक्षता में गृह सचिव, विदेश सचिव, सचिव, रक्षा मंत्रालय, सचिव, राजस्व विभाग, सचिव, रसायन और पेट्रोरसायन विभाग, सचिव, रक्षा अनुसंधान एवं विकास विभाग और सचिव, वाणिज्य विभाग के साथ एक उच्च स्तरीय संचालन समिति की स्थापना की गई है। \r\n<br>\r\nराष्ट्रीय प्राधिकरण सीडब्ल्यूसी अधिनियम के कार्यान्वयन, ओपीसीडब्ल्यू और समझौता के अन्य पक्षकार राज्यों (देशों) के साथ संपर्क, घोषणाओं को समय पर प्रस्तुत करने, ओपीसीडब्ल्यू निरीक्षणों का समन्वय करने आदि सहित भारत के संधि दायित्वों को पूरा करने के लिए उत्तरदायी है।\r\n<br>\r\n\r\n<br>\r\n<strong>प्रत्यक्ष लाभ अंतरण (डीबीटी) मिशन</strong>\r\n<br>\r\nडीबीटी एक प्रमुख सुधार पहल है जिसमें आधार का उपयोग करके लक्षित लाभार्थियों को सीधे लाभ, नकद या वस्तु के रूप में, वितरित किया जाता है। यह वितरण प्रक्रियाओं में दक्षता और समावेश की परिकल्पना करता है जिससे सिस्टम में अधिक जवाबदेही और पारदर्शिता आती है।\r\n<br>\r\nडीबीटी मिशन को डीबीटी के कार्यान्वयन के लिए एक नोडल केंद्र के रूप में कार्य करने के लिए योजना आयोग में बनाया गया था। मिशन को 13 जुलाई को व्यय विभाग को हस्तांतरित कर दिया गया था और 14.09.2015 से मंत्रिमंडल सचिवालय में स्थानांतरित कर दिया गया था। \r\n <br><br>\r\n<strong>प्रमुख वैज्ञानिक सलाहकार का कार्यालय (पीएसए का कार्यालय)</strong><br>\r\n\r\nभारत सरकार के प्रमुख वैज्ञानिक सलाहकार का कार्यालय (पीएसए का कार्यालय) की स्थापना नवंबर 1999 में निम्नलिखित के लिए की गई थी: \r\n\r\n•	बहु अनुप्रयोगों के लिए नवाचारों और सहायता पद्धतियों के सृजन हेतु नीतियां, कार्यनीतियां और मिशन तैयार करना,\r\n•	भारत सरकार के विभागों, संस्थाओं एवं उद्योग की सहभागिता से महत्वपूर्ण अवसंरचना, आर्थिक और सामाजिक क्षेत्रों में विज्ञान एवं प्रौद्योगिकी संबंधी कार्य सृजित करना।\r\n\r\nप्रमुख वैज्ञानिक सलाहकार का कार्यालय प्रधान मंत्री की विज्ञान, प्रौद्योगिकी और नवाचार संबंधी सलाहकार परिषद् (पीएम-एसटीआईएसी) को भी सेवा प्रदान करता है।\r\n\r\nप्रमुख वैज्ञानिक सलाहकार के कार्यालय को अगस्त, 2018 में प्रशासनिक रूप से मंत्रिमंडल सचिवालय के नियंत्रण में कर दिया गया है। \r\n', 'text', 7, 1, NULL, NULL, NULL, '2026-04-30 06:34:38', '2026-10-12 10:04:51'),
