\\" stroke-width=\\"1.3\\" stroke-linecap=\\"round\\"\\r\\n                        stroke-linejoin=\\"round\\" />\\r\\n                </svg>\\r\\n                वेबसाइट देखें</a>\\r\\n        </div>\\r\\n\\r\\n        <div class=\\"link-card\\">\\r\\n            <span class=\\"link-text\\">डिजिलॉकर</span>\\r\\n            <a href=\\"https://www.digilocker.gov.in/\\" class=\\"visit-btn\\"><i class=\\"fas fa-external-link-alt\\"></i>\\r\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 14 14\\" fill=\\"none\\">\\r\\n                    <path d=\\"M6 2H2a1 1 0 00-1 1v9a1 1 0 001 1h9a1 1 0 001-1V8\\" stroke=\\"currentColor\\" stroke-width=\\"1.3\\"\\r\\n                        stroke-linecap=\\"round\\" />\\r\\n                    <path d=\\"M9 1h4v4M13 1L7 7\\" stroke=\\"currentColor\\" stroke-width=\\"1.3\\" stroke-linecap=\\"round\\"\\r\\n                        stroke-linejoin=\\"round\\" />\\r\\n                </svg>\\r\\n                वेबसाइट देखें</a>\\r\\n        </div>\\r\\n    </div>\\r\\n</div>","css":"* {\\r\\n    margin: 0;\\r\\n    padding: 0;\\r\\n    box-sizing: border-box;\\r\\n    font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\\r\\n}\\r\\n\\r\\nbody {\\r\\n    background-color: #fcfcfc; /* Light background as seen in image */\\r\\n    display: flex;\\r\\n    justify-content: center;\\r\\n    padding: 40px 20px;\\r\\n}\\r\\n\\r\\n.container {\\r\\n    width: 100%;\\r\\n    max-width: 900px;\\r\\n}\\r\\n\\r\\n/* Search Bar Styling */\\r\\n.search-container {\\r\\n    position: relative;\\r\\n    margin-bottom: 25px;\\r\\n}\\r\\n\\r\\n.search-icon {\\r\\n    position: absolute;\\r\\n    left: 15px;\\r\\n    top: 50%;\\r\\n    transform: translateY(-50%);\\r\\n    color: #4a7c92;\\r\\n    font-size: 18px;\\r\\n}\\r\\n\\r\\n.search-container input {\\r\\n    width: 100%;\\r\\n    padding: 12px 12px 12px 45px;\\r\\n    border: 1.5px solid #4a74d4; /* Blue border */\\r\\n    border-radius: 6px;\\r\\n    font-size: 16px;\\r\\n    color: #555;\\r\\n    outline: none;\\r\\n}\\r\\n\\r\\n/* Links Wrapper */\\r\\n.links-wrapper {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    gap: 12px; /* Spacing between cards */\\r\\n}\\r\\n\\r\\n/* Individual Link Card */\\r\\n.link-card {\\r\\n    background: #fff;\\r\\n    border: 1px solid #e0e0e0;\\r\\n    border-radius: 8px;\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    padding: 10px 15px;\\r\\n    transition: box-shadow 0.3s ease;\\r\\n}\\r\\n\\r\\n.link-card:hover {\\r\\n    box-shadow: 0 2px 8px rgba(0,0,0,0.05);\\r\\n}\\r\\n\\r\\n.link-text {\\r\\n    font-size: 16px;\\r\\n    color: #333;\\r\\n    font-weight: 500;\\r\\n}\\r\\n\\r\\n/* Visit Website Button */\\r\\n.visit-btn {\\r\\n    background-color: #dbe4ff; /* Very light blue background */\\r\\n    color: #2c54c1; /* Strong blue text */\\r\\n    text-decoration: none;\\r\\n    font-size: 12px;\\r\\n    font-weight: bold;\\r\\n    padding: 10px 20px;\\r\\n    border-radius: 6px;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 8px;\\r\\n    transition: background 0.3s ease;\\r\\n}\\r\\n\\r\\n.visit-btn:hover {\\r\\n    background-color: #c9d6ff;\\r\\n}\\r\\n\\r\\n.visit-btn i {\\r\\n    font-size: 14px;\\r\\n}\\r\\n\\r\\n/* Responsive adjustment */\\r\\n@media (max-width: 600px) {\\r\\n    .link-card {\\r\\n        flex-direction: column;\\r\\n        align-items: flex-start;\\r\\n        gap: 10px;\\r\\n    }\\r\\n    .visit-btn {\\r\\n        width: 100%;\\r\\n        justify-content: center;\\r\\n    }\\r\\n}","js":""}', 0, 1, '2026-04-29 10:29:58', '2026-09-15 11:27:48', NULL),
	(29, 'कैबिनेट सचिव', '/cabinet-secretariat/cabinet-secretary', NULL, NULL, NULL, NULL, NULL, '{"html":"<!DOCTYPE html>\\r\\n<html lang=\\"hi\\">\\r\\n<head>\\r\\n  <meta charset=\\"UTF-8\\">\\r\\n  <title>प्रोफ़ाइल</title>\\r\\n  <link rel=\\"stylesheet\\" href=\\"style.css\\">\\r\\n</head>\\r\\n<body>\\r\\n\\r\\n<div class=\\"container\\">\\r\\n  \\r\\n  <div class=\\"profile-card\\">\\r\\n    \\r\\n    <!-- Left Image -->\\r\\n    <div class=\\"profile-image\\">\\r\\n      <img src=\\"http://localhost:3000/images/our-team/a.jpg\\" alt=\\"प्रोफ़ाइल फ़ोटो\\">\\r\\n    </div>\\r\\n\\r\\n    <!-- Right Content -->\\r\\n    <div class=\\"profile-content\\">\\r\\n     <h2>डॉ. टी. वी. सोमानथन</h2><h3><strong>कैबिनेट सचिव</strong></h3><p>डॉ. टी. वी. सोमानथन 1987 बैच, तमिलनाडु कैडर के एक प्रतिष्ठित भारतीय प्रशासनिक सेवा (IAS) अधिकारी हैं, जो वर्तमान में <strong>30 अगस्त 2024</strong> से <strong>भारत के कैबिनेट सचिव</strong> के रूप में कार्यरत हैं। तीन दशकों से अधिक के शानदार करियर के साथ, उन्होंने राष्ट्रीय और अंतर्राष्ट्रीय दोनों स्तरों पर कई प्रमुख पदों पर कार्य किया है।</p><p>कैबिनेट सचिव के रूप में अपनी नियुक्ति से पहले, डॉ. सोमानथन ने <strong>व्यय विभाग</strong> के प्रमुख के रूप में <strong>भारत के वित्त सचिव</strong> के रूप में सेवा दी। केंद्र में उनकी पिछली भूमिकाओं में <strong>प्रधानमंत्री कार्यालय (PMO) में अपर सचिव</strong> और <strong>संयुक्त सचिव</strong> के रूप में कार्य करना शामिल है, जहाँ उन्होंने विभिन्न शासन और नीतिगत पहलों में महत्वपूर्ण भूमिका निभाई।</p><p>अंतर्राष्ट्रीय स्तर पर, डॉ. सोमानथन ने वाशिंगटन, डी.सी. में <strong>विश्व बैंक समूह</strong> में <strong>निदेशक, कॉर्पोरेट मामलों</strong> के रूप में कार्य किया, जहाँ वे शुरू में इसके प्रतिष्ठित <strong>यंग प्रोफ़ेशनल्स प्रोग्राम</strong> के माध्यम से शामिल हुए थे। सार्वजनिक वित्त और आर्थिक नीति में उनकी विशेषज्ञता को भारत और विदेशों दोनों में व्यापक रूप से मान्यता मिली है।</p><p>कॉर्पोरेट मामलों के मंत्रालय में, उन्होंने <strong>संयुक्त सचिव</strong> के रूप में महत्वपूर्ण योगदान दिया, जिसमें उन्होंने उन सुधारों और नियामक ढांचों पर ध्यान केंद्रित किया जिन्होंने कॉर्पोरेट प्रशासन को उन्नत बनाया।</p><h3><strong>शैक्षणिक योग्यताएँ</strong></h3><ul><li><strong>अर्थशास्त्र में पीएच.डी.</strong>, कलकत्ता विश्वविद्यालय</li><li><strong>एग्जीक्यूटिव डेवलपमेंट प्रोग्राम</strong>, हार्वर्ड बिजनेस स्कूल</li><li><strong>चार्टर्ड अकाउंटेंट (CA)</strong></li><li><strong>कॉस्ट अकाउंटेंट (CMA)</strong></li><li><strong>कंपनी सेक्रेटरी (CS)</strong></li></ul><p>डॉ. सोमानथन व्यावहारिक प्रशासनिक अनुभव के साथ गहन अकादमिक ज्ञान को जोड़ते हैं, जो उन्हें भारत के सबसे सम्मानित सिविल सेवकों में से एक बनाता है। उनकी पेशेवर यात्रा उत्कृष्टता, अखंडता और राष्ट्र-निर्माण के प्रति प्रतिबद्धता को दर्शाती है।</p>\\r\\n\\r\\n    </div>\\r\\n\\r\\n  </div>\\r\\n\\r\\n</div>\\r\\n\\r\\n</body>\\r\\n</html>","css":"body {\\r\\n  margin: 0;\\r\\n  font-family: Arial, sans-serif;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  display: flex;\\r\\n  justify-content: center;\\r\\n  padding: 40px;\\r\\n}\\r\\n\\r\\n.profile-card {\\r\\n  display: flex;\\r\\n  gap: 40px;\\r\\n  padding: 30px;\\r\\n  max-width: 1100px;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.profile-image img {\\r\\n  width: 280px;\\r\\n  height: auto;\\r\\n  object-fit: cover;\\r\\n}\\r\\n\\r\\n.profile-content {\\r\\n  flex: 1;\\r\\n}\\r\\n\\r\\n.profile-content h1 {\\r\\n  margin: 0;\\r\\n  font-size: 24px;\\r\\n  color: #1a2a5a;\\r\\n}\\r\\n\\r\\n.profile-content h3 {\\r\\n  margin-top: 5px;\\r\\n  font-size: 14px;\\r\\n  letter-spacing: 1px;\\r\\n}\\r\\n\\r\\n.profile-content p {\\r\\n  font-size: 14px;\\r\\n  line-height: 1.6;\\r\\n  color: #333;\\r\\n}\\r\\n\\r\\n.profile-content h4 {\\r\\n  margin-top: 20px;\\r\\n  font-size: 16px;\\r\\n}\\r\\n\\r\\n.profile-content ul {\\r\\n  padding-left: 20px;\\r\\n}\\r\\n\\r\\n.profile-content ul li {\\r\\n  margin-bottom: 8px;\\r\\n  font-size: 14px;\\r\\n}","js":""}', 0, 1, '2026-05-05 10:29:48', '2026-09-15 09:19:38', NULL),
	(32, 'Persona Media', '/persona/media', NULL, NULL, NULL, NULL, NULL, '{"html":" <div class=\\"card-container\\">\\r\\n\\r\\n    <!-- Acts and Policies Card -->\\r\\n    <a href=\\"#acts-policies\\" class=\\"info-card\\">\\r\\n\\r\\n      <svg class=\\"card-icon\\"\\r\\n           viewBox=\\"0 0 40 40\\"\\r\\n           fill=\\"none\\"\\r\\n           xmlns=\\"http://www.w3.org/2000/svg\\">\\r\\n\\r\\n        <rect x=\\"4\\" y=\\"3\\" width=\\"21\\" height=\\"27\\"\\r\\n              rx=\\"2\\" stroke=\\"currentColor\\"\\r\\n              stroke-width=\\"1.7\\"/>\\r\\n\\r\\n        <path d=\\"M9 9H20M9 13H20M9 17H17M9 21H15\\"\\r\\n              stroke=\\"currentColor\\"\\r\\n              stroke-width=\\"1.5\\"\\r\\n              stroke-linecap=\\"round\\"/>\\r\\n\\r\\n        <path d=\\"M21 24L26 19L34 27L29 32Z\\"\\r\\n              stroke=\\"currentColor\\"\\r\\n              stroke-width=\\"1.7\\"\\r\\n              stroke-linejoin=\\"round\\"/>\\r\\n\\r\\n        <path d=\\"M25 20L29 16L37 24L33 28\\"\\r\\n              stroke=\\"currentColor\\"\\r\\n              stroke-width=\\"1.7\\"\\r\\n              stroke-linejoin=\\"round\\"/>\\r\\n\\r\\n        <path d=\\"M26 33L22 36L22 30\\"\\r\\n              stroke=\\"currentColor\\"\\r\\n              stroke-width=\\"1.7\\"\\r\\n              stroke-linejoin=\\"round\\"/>\\r\\n\\r\\n      </svg>\\r\\n\\r\\n      <span class=\\"card-text\\">\\r\\n        Know about our <strong>Acts and Policies</strong>\\r\\n      </span>\\r\\n\\r\\n      <span class=\\"arrow-btn\\" aria-hidden=\\"true\\">\\r\\n        <svg width=\\"21\\" height=\\"21\\" viewBox=\\"0 0 24 24\\"\\r\\n             fill=\\"none\\" stroke=\\"currentColor\\"\\r\\n             stroke-width=\\"1.7\\">\\r\\n          <path d=\\"M4 12H19M13 6L19 12L13 18\\"/>\\r\\n        </svg>\\r\\n      </span>\\r\\n\\r\\n    </a>\\r\\n\\r\\n    <!-- Photos Card -->\\r\\n    <a href=\\"#photos\\" class=\\"info-card\\">\\r\\n\\r\\n      <svg class=\\"card-icon\\"\\r\\n 