	(12148, 125, 'केवल उन मंत्रालयों/विभागों के साथ परामर्श जिनका कार्य प्रस्ताव से प्रभावित होने की संभावना है।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3337.pdf', 'application/pdf', '21.5 KB', 1, '2026-06-10 09:09:15', '2016-05-11 00:00:00'),
	(12149, 125, 'उस दिनांक (दिनांकों) को दर्शाना जब अंतर-मंत्रालयी परामर्श की प्रक्रिया के दौरान प्रायोजक मंत्रालय/विभाग को टिप्पणियां प्राप्त होती हैं।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3338.pdf', 'application/pdf', '20.8 KB', 1, '2026-06-10 09:09:15', '2015-09-30 00:00:00'),
	(12150, 125, 'अंतर-मंत्रालयी परामर्श की संपूर्ण प्रक्रिया दो सप्ताह में पूरा किया जाना।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3339.pdf', 'application/pdf', '44.5 KB', 1, '2026-06-10 09:09:15', '2014-06-20 00:00:00'),
