	(12154, 125, 'व्यय वित्त समिति/पीआईबी सहित विभिन्न मूल्यांकन निकायों द्वारा विचार किए जाने वाले मामलों में अंतर-मंत्रालयी परामर्श प्रक्रिया।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3343.pdf', 'application/pdf', '354.7 KB', 1, '2026-06-10 09:09:15', '2008-03-25 00:00:00'),
	(12155, 125, 'सचिवों की समिति (CoS) द्वारा विचार किए जाने वाले मामलों में अंतर-मंत्रालयी परामर्श प्रक्रिया।  मंत्रिमंडल/मंत्रिमंडल समितियों के निर्देश पर सीओएस द्वारा विचार किए जाने वाले मामलों में संबंधित सचिव द्वारा प्रभारी मंत्री का अनुमोदन अथवा अन्यथा के बारे में सूचित करने की आवश्यकता।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3344.pdf', 'application/pdf', '310.2 KB', 1, '2026-06-10 09:09:15', '2006-04-04 00:00:00'),
	(12156, 125, 'प्रक्रियागत आवश्यकताएं और त्रुटि रहित मंत्रिमंडल नोट तैयार करना।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3345.pdf', 'application/pdf', '1.1 MB', 1, '2026-06-10 09:09:15', '2005-03-31 00:00:00'),
	(12157, 125, 'मंत्रिमंडल नोटों में उन दिनांकों का उल्लेख करना,  जब परामर्श  किए गए मंत्रालयों/विभागों से टिप्पणियां प्राप्त हुईं।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3346.pdf', 'application/pdf', '445.7 KB', 1, '2026-06-10 09:09:15', '2004-12-01 00:00:00'),
	(12158, 126, 'कार्योत्तर अनुमोदन प्राप्त करने या सूचना के लिए मंत्रिमंडल/मंत्रिमंडल समिति हेतु नोट समय पर प्रस्तुत करने के संबंध में निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3347.pdf', 'application/pdf', '66.4 KB', 1, '2026-06-10 09:09:15', '2021-09-16 00:00:00'),
	(12159, 126, 'ई-समीक्षा पोर्टल के माध्यम से समझौता ज्ञापनों (एमओयू) की भी संरचित निगरानी।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3350.pdf', 'application/pdf', '793.2 KB', 1, '2026-06-10 09:09:15', '2019-10-15 00:00:00'),
	(12160, 126, 'समझौता-ज्ञापन/अनुबंध (करार) पर हस्ताक्षर करने के उपरांत शीघ्र सूचना (एक माह के भीतर) के संबंध में दिनांक 21.03.2018 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3351.pdf', 'application/pdf', '502.1 KB', 1, '2026-06-10 09:09:15', '2018-06-01 00:00:00'),
	(12161, 126, 'कार्योत्तर अनुमोदन प्राप्त करने के लिए एक माह के भीतर मंत्रिमंडल/मंत्रिमंडल समिति हेतु नोट प्रस्तुत करने के संबंध में दिनांक 29.06.2011, 24.06.2015, 14.08.2015,  10.11.2016,  06.02.2017 और 08.09.2017 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3352.pdf', 'application/pdf', '482.9 KB', 1, '2026-06-10 09:09:15', '2018-03-21 00:00:00'),
	(12162, 126, 'मंत्रिमंडल/मंत्रिमंडल समितियों के सूचनार्थ नोट को एक माह की निर्धारित अवधि के भीतर रखने के संबंध में दिनांक 06.02.2017 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3353.pdf', 'application/pdf', '1.3 MB', 1, '2026-06-10 09:09:15', '2017-09-08 00:00:00'),
	(12163, 126, 'संस्कृति, विज्ञान और प्रौद्योगिकी संबंधी करार (एमओयू) किए जाने पर मंत्रिमंडल सचिवालय को तत्काल सूचना के साथ हस्ताक्षरित करार की प्रति भेजना तथा एक महीने के भीतर नोट अग्रेषित करना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3354.pdf', 'application/pdf', '671.8 KB', 1, '2026-06-10 09:09:15', '2017-02-06 00:00:00'),
	(12164, 126, 'कार्योत्तर अनुमोदन प्राप्त करने या सूचना के लिए नोट का एक महीने की निर्धारित अवधि के भीतर अग्रेषण।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3355.pdf', 'application/pdf', '44.9 KB', 1, '2026-06-10 09:09:15', '2016-11-10 00:00:00'),
	(12165, 126, 'मंत्रालयों/विभागों द्वारा हस्ताक्षरित समझौता-ज्ञापनों को उन पर हस्ताक्षर करने के एक महीने के भीतर मंत्रिमंडल के समक्ष लाया जाना। इसमें विलम्ब होने पर विशिष्ट कारणों और औचित्य का भी उल्लेख करना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3356.pdf', 'application/pdf', '283.9 KB', 1, '2026-06-10 09:09:15', '2015-08-14 00:00:00'),
	(12166, 126, 'अंतिम समय पर विदेशों/संगठनों के साथ समझौता-ज्ञापनों पर हस्ताक्षर करने के लिए भारत सरकार (कार्यकरण नियम) नियम, 1961 के नियम 12 का प्रयोग करने की आवश्यकता से बचने के प्रयास करना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3357.pdf', 'application/pdf', '1.6 MB', 1, '2026-06-10 09:09:15', '2015-06-24 00:00:00'),
	(12167, 126, 'मंत्रालयों द्वारा समझौता-ज्ञापन के मार्ग को चुनने का औचित्य देना।  मंत्रिमंडल का पूर्व अनुमोदन अपेक्षित है और सांविधिक निकायों सहित अधीनस्थ/संबद्ध कार्यालय भी इन्हीं निर्देशों का पालन करेंगे।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3358.pdf', 'application/pdf', '10.5 KB', 1, '2026-06-10 09:09:15', '2015-06-03 00:00:00'),
	(12168, 126, 'समझौता ज्ञापन के संबंध में दिनांक 09.02.2015 के निर्देशों का सभी मंत्रालय/विभाग/कार्यालयों पर लागू होना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3359.pdf', 'application/pdf', '109.8 KB', 1, '2026-06-10 09:09:15', '2015-04-24 00:00:00'),
	(12169, 126, 'समझौता ज्ञापन के मार्ग को चुनने का औचित्य देना और मौजूदा समझौता-ज्ञापनों की सूची और स्थिति संलग्न करना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3360.pdf', 'application/pdf', '36.9 KB', 1, '2026-06-10 09:09:15', '2015-02-09 00:00:00'),
